from pathlib import Path
from urllib.parse import unquote,urlsplit
import json,sys
from scripts.check_docs import links,anchors
root=Path(sys.argv[1])
errors=[]
count=0
active=[p for p in root.rglob('*') if p.is_file() and 'frozen' not in p.relative_to(root).parts]
for source in active:
 if source.suffix in {'.md','.py','.json'}:
  for n,line in enumerate(source.read_text().splitlines(),1):
   if line.rstrip()!=line: errors.append(f'trailing whitespace: {source}:{n}')
 if source.suffix!='.md': continue
 for number,destination in links(source.read_text()):
  url=urlsplit(destination)
  if url.scheme or url.netloc: continue
  count+=1
  target=(source.parent/unquote(url.path)).resolve() if url.path else source.resolve()
  if not target.exists(): errors.append(f'missing path: {source}:{number}: {destination}')
  elif url.fragment and target.suffix=='.md' and unquote(url.fragment) not in anchors(target.read_text()): errors.append(f'missing anchor: {source}:{number}: {destination}')
print(json.dumps({'active_markdown':sum(p.suffix=='.md' for p in active),'links_checked':count,'errors':errors},sort_keys=True))
raise SystemExit(bool(errors))
